def smooth_orderings(sizes, d):
    vals = sorted(sizes)
    n = len(vals)
    near = [[j for j in range(n) if abs(vals[i] - vals[j]) <= d] for i in range(n)]
    ways = [[0] * n for _ in range(1 << n)]       # ways[sent][last]
    for i in range(n):
        if i == 0 or vals[i] != vals[i - 1]:      # start only from the first copy of a size
            ways[1 << i][i] = 1
    for sent in range(1 << n):
        row = ways[sent]
        for last in range(n):
            w = row[last]
            if not w:
                continue
            for j in near[last]:
                if sent >> j & 1:
                    continue
                if j and vals[j] == vals[j - 1] and not sent >> (j - 1) & 1:
                    continue                      # an equal size must wait for its earlier copy
                ways[sent | 1 << j][j] += w
    return sum(ways[-1])

