from math import factorial


def smooth_orderings(sizes, d):
    left = Counter(sizes)
    kinds = sorted(left)
    if kinds[-1] - kinds[0] <= d:
        total = factorial(len(sizes))
        for c in left.values():
            total //= factorial(c)
        return total

    def walk(last, placed):
        if placed == len(sizes):
            return 1
        total = 0
        for v in kinds:
            if left[v] and (last is None or abs(v - last) <= d):
                left[v] -= 1
                total += walk(v, placed + 1)
                left[v] += 1
        return total

    return walk(None, 0)
